#include <stdio.h>

int main() {
    int i;
    for (i = 10; i >= 1; i--)
        printf("%d\n", i);
    printf("LIFTOFF\n");
    return 0;
}

#include <stdio.h>

int main() {
    int a = 1071, b = 462, r;
    while (b != 0) {
        r = a % b;
        a = b;
        b = r;
    }
    printf("GCD = %d\n", a);
    return 0;
}

#include <stdio.h>

int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}

int main() {
    int n;
    for (n = 1; n <= 7; n++)
        printf("%d %d\n", n, fact(n));
    return 0;
}

#include <stdio.h>
#include <math.h>

double hyp(double a, double b) {
    return sqrt(a * a + b * b);
}

int main() {
    printf("%.2f\n", hyp(3.0, 4.0));
    printf("%.2f\n", hyp(5.0, 12.0));
    return 0;
}

#include <stdio.h>

int main() {
    int i;
    for (i = 9; i >= 0; i--)
        putchar('0' + i);
    return 0;
}

#include <stdio.h>

int main() {
    int x = 12;
    int y = (x << 3) + (x << 1);
    printf("%d\n", y);
    return 0;
}

#include <stdio.h>

int main() {
    int i;
    for (i = 1; i <= 15; i++) {
        if (i % 15 == 0) printf("FizzBuzz\n");
        else if (i % 3 == 0) printf("Fizz\n");
        else if (i % 5 == 0) printf("Buzz\n");
        else printf("%d\n", i);
    }
    return 0;
}

#include <stdio.h>

struct rect {
    int w;
    int h;
};

int main() {
    struct rect a = {3, 4};
    struct rect b = {10, 2};
    printf("area a = %d\n", a.w * a.h);
    printf("area b = %d\n", b.w * b.h);
    return 0;
}

program SwapIt;
var
  x, y: integer;

procedure Swap(var a, b: integer);
var
  t: integer;
begin
  t := a;
  a := b;
  b := t;
end;

begin
  x := 1;
  y := 2;
  Swap(x, y);
  writeln('x = ', x, ', y = ', y);
end.

program Doubling;
var
  n, steps: integer;
begin
  n := 1;
  steps := 0;
  repeat
    n := n * 2;
    steps := steps + 1;
  until n > 1000;
  writeln(steps);
  writeln(n);
end.

#include <stdio.h>

int main() {
    int n = 181, count = 0, i;
    for (i = 0; i < 8; i++) {
        if (n & 1) count++;
        n >>= 1;
    }
    printf("%d\n", count);
    return 0;
}

